from __future__ import annotations

import hashlib
import json
import time
from datetime import UTC, datetime
from decimal import Decimal
from pathlib import Path
from typing import Any

from packages.common.pg_native import PostgresMigration, apply_schema_migrations, connect_postgres
from .models import BroadcastState, StockAlert, StockInstrument, StockQuote
from .state_machine import (AGGREGATION_SECONDS, FOLLOWUP_SECONDS, PRICE_LOCK_SECONDS, PRICE_STEP_PERCENT, state_from_dict, state_to_dict)

SCHEMA_SQL="""
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value text NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS instruments(symbol text PRIMARY KEY,market text NOT NULL,price_precision integer NOT NULL,active boolean NOT NULL DEFAULT true,last_price text,observed_at bigint,change_1h text,change_24h text,last_error text,updated_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS price_samples(symbol text NOT NULL,observed_at bigint NOT NULL,price text NOT NULL,PRIMARY KEY(symbol,observed_at));
CREATE INDEX IF NOT EXISTS idx_stock_market_samples_time ON price_samples(symbol,observed_at);
CREATE TABLE IF NOT EXISTS trigger_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_key text NOT NULL UNIQUE,symbol text NOT NULL,market text NOT NULL,"window" text NOT NULL,tier text NOT NULL,direction text NOT NULL,change_percent text NOT NULL,current_price text NOT NULL,title text NOT NULL,content text NOT NULL,status text NOT NULL,error text,odaily_external_error_counted integer NOT NULL DEFAULT 0,observed_at bigint NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,details_json jsonb NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_stock_market_events_recent ON trigger_events(created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS broadcast_state(id integer PRIMARY KEY CHECK(id=1),payload jsonb NOT NULL);
"""
CHECKSUM=hashlib.sha256(SCHEMA_SQL.encode()).hexdigest()

class PostgresStockMarketStore:
    def __init__(self,path:Path,*,initialize:bool=True):
        self.path=path
        if initialize:self.initialize()
    def initialize(self):
        self.initialize_schema()
        with connect_postgres(schema='stock',application_name='odaily-stock-market-migrate') as c:
            now=int(time.time())
            defaults={'poll_interval_seconds':'30','instrument_refresh_seconds':'3600','last_discovery_at':'0','last_discovery_error':'','last_cycle_at':'0','last_cycle_status':'not_started','last_cycle_error':''}
            for k,v in defaults.items():c.execute("INSERT INTO settings VALUES(%s,%s,%s) ON CONFLICT(key) DO NOTHING",(k,v,now))
    @staticmethod
    def initialize_schema():
        with connect_postgres(schema='stock',application_name='odaily-stock-market-migrate') as c:
            apply_schema_migrations(c,schema='stock',component='stock_market',migrations=(PostgresMigration(1,'stock market persistence',CHECKSUM,lambda x:x.execute(SCHEMA_SQL)),PostgresMigration(2,'Stock external error counter',hashlib.sha256(b"stock.trigger_events.odaily_external_error_counted.v2").hexdigest(),lambda x:x.execute("ALTER TABLE trigger_events ADD COLUMN IF NOT EXISTS odaily_external_error_counted integer NOT NULL DEFAULT 0"))))
    def _one(self,q,p=()):
        with connect_postgres(schema='stock',application_name='odaily-stock-market') as c:return c.execute(q,p).fetchone()
    def _setting(self,key,default=''):
        r=self._one('SELECT value FROM settings WHERE key=%s',(key,));return str(r['value']) if r else default
    def get_setting(self,key,default='')->str:return self._setting(key,default)
    def set_setting(self,key,value):
        with connect_postgres(schema='stock',application_name='odaily-stock-market') as c:c.execute("INSERT INTO settings VALUES(%s,%s,%s) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(key,value,int(time.time())))
    def last_discovery_at(self):
        try:return int(self.get_setting('last_discovery_at','0'))
        except ValueError:return 0
    def list_instruments(self):
        with connect_postgres(schema='stock',application_name='odaily-stock-market') as c:rows=c.execute('SELECT symbol,market,price_precision FROM instruments WHERE active ORDER BY symbol').fetchall()
        return [StockInstrument(str(r['symbol']),r['market'],int(r['price_precision'])) for r in rows]
    def sync_instruments(self,instruments:list[StockInstrument],*,now:int):
        with connect_postgres(schema='stock',application_name='odaily-stock-market') as c:
            with c.transaction():
                c.execute('UPDATE instruments SET active=false,updated_at=%s',(now,))
                for i in instruments:c.execute("INSERT INTO instruments(symbol,market,price_precision,active,updated_at) VALUES(%s,%s,%s,true,%s) ON CONFLICT(symbol) DO UPDATE SET market=excluded.market,price_precision=excluded.price_precision,active=true,last_error=NULL,updated_at=excluded.updated_at",(i.symbol,i.market,i.price_precision,now))
                c.execute("INSERT INTO settings VALUES('last_discovery_at',%s,%s) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(str(now),now));c.execute("INSERT INTO settings VALUES('last_discovery_error','',%s) ON CONFLICT(key) DO UPDATE SET value='',updated_at=excluded.updated_at",(now,))
    def record_discovery_error(self,error:str,*,now:int):self.set_setting('last_discovery_error',error[:1000])
    def record_worker_failure(self,error:str,*,now:int):
        with connect_postgres(schema='stock',application_name='odaily-stock-market') as c:
            for k,v in (('last_cycle_at',str(now)),('last_cycle_status','error'),('last_cycle_error',error[:1000])):c.execute('INSERT INTO settings VALUES(%s,%s,%s) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at',(k,v,now))
    def one_hour_references(self,quotes:dict[str,StockQuote])->dict[str,Decimal]:
        result={}
        with connect_postgres(schema='stock',application_name='odaily-stock-market') as c:
            for symbol,q in quotes.items():
                target=q.observed_at-3600;r=c.execute('SELECT observed_at,price FROM price_samples WHERE symbol=%s AND observed_at<=%s ORDER BY observed_at DESC LIMIT 1',(symbol,target)).fetchone()
                if r and 0<=target-int(r['observed_at'])<=90 and Decimal(r['price'])>0:result[symbol]=Decimal(r['price'])
        return result
    def broadcast_state(self):
        r=self._one('SELECT payload FROM broadcast_state WHERE id=1');payload=r['payload'] if r else None
        if isinstance(payload,str):payload=json.loads(payload)
        return state_from_dict(payload) if payload else BroadcastState()
    def record_cycle(self,*,quotes:dict[str,StockQuote],changes_1h:dict[str,Decimal],state:BroadcastState,alerts:list[StockAlert],errors:dict[str,str],now:int,startup_baseline:bool)->list[StockAlert]:
        claimed=[]
        with connect_postgres(schema='stock',application_name='odaily-stock-market-cycle') as c:
            with c.transaction():
                for symbol,q in quotes.items():
                    c.execute('INSERT INTO price_samples VALUES(%s,%s,%s) ON CONFLICT(symbol,observed_at) DO UPDATE SET price=excluded.price',(symbol,q.observed_at,str(q.price)))
                    c.execute('UPDATE instruments SET last_price=%s,observed_at=%s,change_1h=%s,change_24h=%s,last_error=NULL,updated_at=%s WHERE symbol=%s AND active=true',(str(q.price),q.observed_at,str(changes_1h[symbol]) if symbol in changes_1h else None,str(q.change_24h),now,symbol))
                for symbol,error in errors.items():c.execute('UPDATE instruments SET last_error=%s,updated_at=%s WHERE symbol=%s AND active=true',(error[:1000],now,symbol))
                c.execute("INSERT INTO broadcast_state VALUES(1,%s) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload",(json.dumps(state_to_dict(state),default=str),))
                for alert in alerts:
                    primary=alert.members[0];details={'members':[{'symbol':m.instrument.symbol,'asset_name':m.instrument.asset_name,'changes':{w:str(v) for w,v in m.changes.items()},'current_price':str(m.current_price),'observed_at':datetime.fromtimestamp(m.observed_at,UTC).isoformat()} for m in alert.members]}
                    if alert.headline_diagnostics is not None:details['headline']=alert.headline_diagnostics
                    row=c.execute("""INSERT INTO trigger_events(event_key,symbol,market,"window",tier,direction,change_percent,current_price,title,content,status,observed_at,created_at,updated_at,details_json) VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'publishing',%s,%s,%s,%s) ON CONFLICT(event_key) DO NOTHING RETURNING event_key""",(alert.event_key,primary.instrument.symbol,alert.market,primary.primary_window,alert.tier,alert.direction,str(primary.change_pct),str(primary.current_price),alert.title,alert.content,max(m.observed_at for m in alert.members),now,now,json.dumps(details,ensure_ascii=False))).fetchone()
                    if row:claimed.append(alert)
                status='partial_error' if errors else ('baseline' if startup_baseline else 'ok')
                for k,v in (('last_cycle_at',str(now)),('last_cycle_status',status),('last_cycle_error','; '.join(errors.values())[:1000])):c.execute('INSERT INTO settings VALUES(%s,%s,%s) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at',(k,v,now))
                c.execute('DELETE FROM price_samples WHERE observed_at<%s',(now-3*3600,));c.execute('DELETE FROM trigger_events WHERE id NOT IN (SELECT id FROM trigger_events ORDER BY created_at DESC,id DESC LIMIT 500)')
        return claimed
    def mark_event(self,event_key:str,*,status:str,error:str|None,now:int):
        with connect_postgres(schema='stock',application_name='odaily-stock-market') as c:c.execute('UPDATE trigger_events SET status=%s,error=%s,updated_at=%s WHERE event_key=%s',(status,error[:1000] if error else None,now,event_key))
    def dashboard(self)->dict[str,Any]:
        with connect_postgres(schema='stock',application_name='odaily-stock-market-dashboard') as c:
            instruments=c.execute('SELECT * FROM instruments WHERE active ORDER BY symbol').fetchall();snap=c.execute('SELECT payload FROM broadcast_state WHERE id=1').fetchone();events=c.execute('SELECT * FROM trigger_events ORDER BY created_at DESC,id DESC LIMIT 100').fetchall();settings={str(r['key']):str(r['value']) for r in c.execute('SELECT * FROM settings').fetchall()}
        raw=snap['payload'] if snap else None
        if isinstance(raw,str):raw=json.loads(raw)
        state=state_from_dict(raw) if raw else BroadcastState()
        contracts=[]
        for r in instruments:
            sym=str(r['symbol']);asset=state.assets.get(sym)
            contracts.append({'symbol':sym,'asset_name':sym.removesuffix('USDT'),'market':r['market'],'price_precision':int(r['price_precision']),'last_price':r['last_price'],'observed_at':_iso(r['observed_at']),'change_1h':r['change_1h'],'change_24h':r['change_24h'],'resume_price':str(asset.resume_price) if asset and asset.resume_price is not None else None,'resumed_at':_iso(asset.resumed_at) if asset else None,'trigger_state':{},'price_locks':{d:{'anchor_price':str(l.anchor_price),'extreme_price':str(l.extreme_price),'tier':l.tier,'locked_until':_iso(l.locked_at+PRICE_LOCK_SECONDS)} for d,l in asset.locks.items()} if asset else {},'last_error':r['last_error']})
        recent=[]
        for r in events:
            details=r['details_json'];details=json.loads(details) if isinstance(details,str) else details
            recent.append({'members':details.get('members',[]),'headline':details.get('headline'),'id':int(r['id']),'symbol':r['symbol'],'market':r['market'],'window':r['window'],'tier':r['tier'],'direction':r['direction'],'change_percent':r['change_percent'],'current_price':r['current_price'],'title':r['title'],'content':r['content'],'status':r['status'],'error':r['error'],'observed_at':_iso(r['observed_at']),'created_at':_iso(r['created_at'])})
        return {'poll_interval_seconds':int(settings.get('poll_interval_seconds','30')),'instrument_refresh_seconds':int(settings.get('instrument_refresh_seconds','3600')),'aggregation_seconds':AGGREGATION_SECONDS,'followup_seconds':FOLLOWUP_SECONDS,'price_lock_seconds':PRICE_LOCK_SECONDS,'price_step_percent':str(PRICE_STEP_PERCENT),'pending_groups':[{'market':g.market,'direction':g.direction,'due_at':_iso(g.due_at),'next_at':_iso(g.next_at),'assets':[s.removesuffix('USDT') for s in sorted(g.pending)]} for g in state.groups.values() if g.pending],'contract_count':len(contracts),'contracts':contracts,'recent_events':recent,'last_cycle_at':_iso(int(settings.get('last_cycle_at','0') or 0)),'last_cycle_status':settings.get('last_cycle_status','not_started'),'last_cycle_error':settings.get('last_cycle_error') or None,'last_discovery_at':_iso(int(settings.get('last_discovery_at','0') or 0)),'last_discovery_error':settings.get('last_discovery_error') or None,'generated_at':_iso(int(time.time()))}

def _iso(timestamp:int|None)->str|None:return datetime.fromtimestamp(timestamp,UTC).isoformat() if timestamp is not None else None

__all__=['PostgresStockMarketStore','SCHEMA_SQL']
